class Money:
    """An amount of money in a given currency.

    Instances are immutable: arithmetic operations return new Money objects
    instead of modifying the receiver.  Adding money of different currencies
    is an error.
    """

    __slots__ = ("amount", "currency")

    def __init__(self, amount, currency):
        self.amount = amount
        self.currency = currency

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        if self.currency != other.currency:
            raise ValueError(
                "cannot add money in different currencies: %r and %r"
                % (self.currency, other.currency)
            )
        return Money(self.amount + other.amount, self.currency)

    def __radd__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return self.__add__(other)

    def __sub__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        if self.currency != other.currency:
            raise ValueError(
                "cannot subtract money in different currencies: %r and %r"
                % (self.currency, other.currency)
            )
        return Money(self.amount - other.amount, self.currency)

    def __mul__(self, factor):
        if isinstance(factor, Money):
            return NotImplemented
        return Money(self.amount * factor, self.currency)

    __rmul__ = __mul__

    def __truediv__(self, divisor):
        if isinstance(divisor, Money):
            return NotImplemented
        return Money(self.amount / divisor, self.currency)

    def __neg__(self):
        return Money(-self.amount, self.currency)

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return self.amount == other.amount and self.currency == other.currency

    def __ne__(self, other):
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    def __hash__(self):
        return hash((self.amount, self.currency))

    def __repr__(self):
        return "Money(%r, %r)" % (self.amount, self.currency)

    def __str__(self):
        return "%s %s" % (self.amount, self.currency)
